host_validate(){ local fail=0; echo 'Host validation (no system changes)'; check(){ local n="$1" c="$2"; if command -v "$c" >/dev/null 2>&1; then printf '✓ %s (%s)\n' "$n" "$c"; else printf '✗ %s (%s)\n' "$n" "$c"; fail=1; fi; }; printf 'Architecture: %s\nCPU threads: %s\nRAM: %s\n' "$(uname -m)" "$(getconf _NPROCESSORS_ONLN 2>/dev/null || echo '?')" "$(awk '/MemTotal/{printf "%.0f MiB",$2/1024}' /proc/meminfo 2>/dev/null || echo '?')"; for x in bash gcc g++ make ld bison perl python3 texi2any gawk tar xz bzip2 sha256sum wget curl; do check "$x" "$x"; done; ((fail==0)) || { echo 'Faltan herramientas. Consulta la documentación de tu distribución.'; return 1; }; }
